-- Guarded on name rather than inserted outright. The workbook has since been
-- corrected, so seed.sql now carries both — an unconditional insert here added
-- a second copy of each on any clean rebuild (111 employees instead of 109, and
-- two phantom rows on the KPI scorecard, which inner-joins employees). The
-- guard also makes this file safe to re-run, which it previously was not.
insert into public.employees (sort_order, name, role, department, employment_type, primary_stakeholder, sub_department, contract_organization, tier)
select 108, 'Charles Crankson', 'Project Manager', 'Enrollment & Retention', 'Professional Contractor', 'Alison Cundiff', 'Department Leadership', 'Springboard', '3'
 where not exists (select 1 from public.employees where lower(name) = 'charles crankson');

