select 109, 'Katelyn Graf', 'Senior Manager of Retention', 'Enrollment & Retention', 'Full-Time Employee', 'Alison Cundiff', 'Retention', null, null
 where not exists (select 1 from public.employees where lower(name) = 'katelyn graf');


-- The hub's directory lists staff and student employees together; the original
-- view returned staff only, which dropped 85 people from that page.
create or replace view public.v_hub_directory as
  select name, role, department as dept, employment_type as type,
         primary_stakeholder as stakeholder, sub_department as "subDept",
         contract_organization as org, tier
  from public.employees
  where active
  union all
  select name, coalesce(role_title, job_name) as role, department as dept,
         'Student Employee' as type, supervisor as stakeholder,
         sub_department as "subDept", null as org, null as tier
  from public.student_employees
  where active
  order by dept, "subDept", name;

grant select on public.v_hub_directory to anon, authenticated;

commit;
